-- tips_upload_PSQ.sql
-- Run in Supabase SQL Editor

update public.shco_full_oes set achieve_tips = '["Form a multi-disciplinary patient safety committee with members from medical, nursing, pharmacy, and administration, and hold documented monthly meetings to review safety concerns.","Maintain a register of committee attendance, agenda items, and action-taken records so assessors can verify active participation across disciplines.","During assessor interviews, department heads should be prepared to describe their role in the patient safety committee and cite at least one improvement driven by the committee.","Conduct periodic ward observations to ensure safety committee decisions — such as fall prevention protocols or hand hygiene drives — are visibly implemented at the point of care."]'::jsonb where oe_code = 'PSQ.1.a';
update public.shco_full_oes set achieve_tips = '["Schedule quarterly patient safety programme review meetings and document findings, gaps identified, and improvement actions agreed upon during each session.","Maintain a rolling log of safety improvement opportunities with target dates, responsible persons, and closure status so progress is visible at each review cycle.","Train the quality coordinator to present trend data — such as incident rates or near-miss patterns — at each review meeting to drive evidence-based improvement decisions.","Create a standard review template that captures what was reviewed, what changed, and what the next cycle will focus on, making audit readiness straightforward."]'::jsonb where oe_code = 'PSQ.1.b';
update public.shco_full_oes set achieve_tips = '["Use a Failure Mode and Effects Analysis (FMEA) tool annually on at least one high-risk process such as medication administration or patient handover, and document findings.","Maintain records of proactive risk assessments including risk registers, severity ratings, and the corrective actions taken as a result of each analysis.","Designate a small team each quarter to walk through a critical care area and identify potential hazards before they cause incidents, logging observations and actions formally.","During assessor walkthroughs, staff should be able to explain how a recent risk analysis led to a visible process change, such as a new checklist or labelling practice."]'::jsonb where oe_code = 'PSQ.1.c';
update public.shco_full_oes set achieve_tips = '["Download and display the current WHO or NABH patient safety goals and create a facility-specific action plan showing how each goal is operationalised in your setting.","Assign ownership of each patient safety goal to a department head and maintain documented evidence of implementation, such as signed checklists, training records, or audit results.","Conduct brief daily safety huddles at shift handovers where staff confirm adherence to at least two patient safety goals, and log these huddles as records for assessors.","Display visual cues — wristbands, colour-coded alerts, medication labels — that directly map to adopted patient safety goals so assessors can observe implementation during walkthroughs."]'::jsonb where oe_code = 'PSQ.1.d';
update public.shco_full_oes set achieve_tips = '["Constitute a formal quality improvement committee with representatives from clinical and non-clinical departments, document its charter, terms of reference, and meeting minutes.","Maintain a master quality improvement plan listing active projects, assigned owners, timelines, and current status, reviewed and updated at every committee meeting.","Ensure staff at all levels can articulate the organisation''s quality priorities when interviewed by assessors — conduct internal mock interviews as part of QI awareness training.","Observe quality improvement activities in practice during internal audits — look for whether improvement actions from the previous cycle have been implemented at ward level."]'::jsonb where oe_code = 'PSQ.1.e';
update public.shco_full_oes set achieve_tips = '["Issue a formal appointment letter designating a specific individual as the Quality Coordinator, clearly outlining their responsibilities, authority, and reporting line.","Ensure the Quality Coordinator maintains a structured activity log covering audits conducted, trainings delivered, indicator data compiled, and committee meetings facilitated.","Train the Quality Coordinator to be the primary point of contact during assessor visits, able to retrieve documents, explain QI processes, and demonstrate programme continuity.","Create an SOP defining the Quality Coordinator''s monthly and quarterly responsibilities so the role remains functional even during staff transitions or absences."]'::jsonb where oe_code = 'PSQ.1.f';
update public.shco_full_oes set achieve_tips = '["Define a fixed review calendar for the quality improvement programme — for example, monthly data review and quarterly programme review — and publish it to all department heads.","Document what triggered each improvement cycle, what was changed as a result, and what the measurable outcome was, creating a clear cause-effect trail for assessors.","Use a structured review template that compares current performance against targets, highlights deviations, and records the corrective actions agreed for the next interval.","Train department leads to present department-level quality data at programme reviews so improvement identification is a shared, multi-departmental process rather than top-down only."]'::jsonb where oe_code = 'PSQ.1.g';
update public.shco_full_oes set achieve_tips = '["Develop an annual audit calendar covering clinical, nursing, and support service areas and share it with department heads so audits are planned, not ad hoc.","Use standardised audit tools with scoring rubrics and maintain completed audit forms in a centralised register accessible to the quality team and assessors.","Follow each audit with a documented action plan noting deficiencies found, corrective actions assigned, responsible person, and a target closure date.","Track audit compliance rates as a quality indicator — present the proportion of planned audits completed versus scheduled in your monthly quality report."]'::jsonb where oe_code = 'PSQ.1.h';
update public.shco_full_oes set achieve_tips = '["Establish nursing quality indicators — such as pressure injury rate, medication error rate, and patient falls — and collect data monthly from all inpatient areas.","Hold a monthly nursing quality meeting where ward sisters present their area''s indicator data, identify gaps, and agree on corrective actions, maintaining written minutes.","Train ward-level nursing staff to self-audit using simple observation checklists so that monitoring is continuous, not limited to formal audit visits.","During assessor interviews, nursing staff should be able to cite current values of key nursing indicators and describe one recent improvement action taken in their unit."]'::jsonb where oe_code = 'PSQ.1.i';
update public.shco_full_oes set achieve_tips = '["Define a core set of clinical key performance indicators — covering areas such as surgical site infection, readmission, and medication errors — approved by the quality committee.","Collect indicator data monthly from source departments and compile it in a structured dashboard that shows current value, target, trend, and responsible department.","Conduct a quarterly clinical data review meeting where each indicator is assessed against its benchmark and opportunities for improvement are formally documented.","Train department heads to present their clinical indicator data during assessor interviews and explain what actions were taken when a target was not met."]'::jsonb where oe_code = 'PSQ.2.a';
update public.shco_full_oes set achieve_tips = '["Define and actively track infection control indicators such as healthcare-associated infection rate, hand hygiene compliance, and antibiotic consumption, reporting monthly to the quality committee.","Ensure the Infection Control Officer maintains a structured monthly report with indicator values, trends, and actions taken — available for assessor review at any time.","Conduct regular observation audits of hand hygiene, aseptic technique, and biomedical waste segregation and document findings as part of the infection control indicator system.","During assessor walkthroughs, infection control staff should be able to show data dashboards and explain how a rising infection indicator triggered a specific corrective intervention."]'::jsonb where oe_code = 'PSQ.2.b';
update public.shco_full_oes set achieve_tips = '["Identify managerial indicators such as patient satisfaction scores, staff attendance rates, equipment downtime, and complaint resolution time, and report them monthly.","Maintain a structured managerial performance dashboard reviewed by senior leadership at monthly management meetings, with decisions and action points recorded in minutes.","Link managerial indicator targets to departmental performance reviews so department heads are accountable for data accuracy and improvement actions.","Create an SOP for data collection and reporting timelines for each managerial indicator to ensure consistency and prevent gaps that assessors would flag during review."]'::jsonb where oe_code = 'PSQ.2.c';
update public.shco_full_oes set achieve_tips = '["Define patient safety indicators including incident rates, near-miss frequency, patient fall rates, and medication error rates, and monitor them with monthly data collection.","Display patient safety indicator trends on a quality board visible to staff, showing whether the facility is improving, stable, or requires urgent action on each metric.","Ensure the incident management team links safety indicator data to specific events — assessors will look for evidence that data drives action, not just reporting.","During assessor interviews, safety committee members should be able to quote current indicator values and describe at least one recent patient safety improvement driven by data."]'::jsonb where oe_code = 'PSQ.2.d';
update public.shco_full_oes set achieve_tips = '["Establish a monthly data verification protocol where the quality team cross-checks reported indicator values against source documents such as registers, discharge summaries, and audit forms.","Maintain a data verification log noting who verified each dataset, when, any discrepancies found, and how they were corrected, making the process transparent to assessors.","Train data collectors in each department on accurate documentation and standardised data entry so that verification consistently finds minimal errors.","Use verified data to populate a monthly quality analysis report that identifies at least two improvement opportunities each cycle, with documented follow-up plans."]'::jsonb where oe_code = 'PSQ.2.e';
update public.shco_full_oes set achieve_tips = '["Maintain a clinical audit register listing all audits conducted, the parameters assessed, audit scores, findings, and the improvement actions implemented, updated after every audit cycle.","Develop standardised clinical audit tools for key processes such as consent documentation, surgical checklist compliance, and medication prescribing, using them consistently across departments.","Ensure clinical audit findings are formally presented to the quality committee with documented action-taken records so that improvement is traceable from audit to outcome.","Train staff who will be interviewed by assessors to describe a recent clinical audit they participated in, including what was found and what changed as a result."]'::jsonb where oe_code = 'PSQ.3.a';
update public.shco_full_oes set achieve_tips = '["Document a formal list of audit parameters approved by the quality committee, covering clinical care, documentation quality, infection control, and support services.","Review and update audit parameters annually based on incident trends, quality indicator performance, and accreditation feedback to ensure they remain relevant and comprehensive.","Make the audit parameter list part of the department''s annual quality plan so every team knows in advance what will be audited and to what standard.","Ensure audit parameters are linked to measurable criteria — for example, ''100% of surgical patients have signed consent forms'' — so audit results are objective and assessor-verifiable."]'::jsonb where oe_code = 'PSQ.3.b';
update public.shco_full_oes set achieve_tips = '["Maintain attendance records from clinical audit meetings showing that both medical and nursing staff are consistently present and actively contributing to discussions.","Assign at least one doctor and one senior nurse as mandatory members of the clinical audit team for each audit cycle, with their names documented in the audit report.","Train medical and nursing staff in basic audit methodology — including data collection, gap analysis, and action planning — so participation is meaningful and skill-based.","During assessor interviews, both a doctor and a nurse from a clinical department should be able to describe their direct involvement in a recent audit and its outcome."]'::jsonb where oe_code = 'PSQ.3.c';
update public.shco_full_oes set achieve_tips = '["For every clinical audit finding, create a corrective action plan with specific steps, a named responsible person, a target completion date, and a re-audit date to confirm closure.","Maintain a remedial action tracker reviewed monthly at quality committee meetings, noting which actions are open, overdue, or closed with evidence of implementation.","Conduct follow-up audits within 90 days of the original audit to verify that remedial measures have been implemented and have resulted in measurable improvement.","Train department heads to present the status of corrective actions during management meetings so accountability for implementation is embedded at a leadership level."]'::jsonb where oe_code = 'PSQ.3.d';
update public.shco_full_oes set achieve_tips = '["Maintain an active list of quality improvement projects with each project''s objective, methodology, team members, current phase, and measurable outcome target.","Use a structured improvement framework — such as PDCA or DMAIC — for each project and document each phase so assessors can follow the logic from problem identification to result.","Select QI project topics based on incident data, indicator trends, or audit findings so projects address real operational gaps rather than theoretical priorities.","Present QI project outcomes — with before-and-after data — at the quality committee meeting and retain these presentations as evidence of continuous improvement activity."]'::jsonb where oe_code = 'PSQ.3.e';
update public.shco_full_oes set achieve_tips = '["Measure safety culture annually using a validated staff survey and publish results to all staff, along with the management''s action plan in response to the findings.","Track sentinel events and near-misses as safety culture indicators — a rising near-miss reporting rate signals an improving culture of openness, and this data should be presented to assessors.","Ensure leadership visibly participates in patient safety activities such as safety walkrounds, hand hygiene campaigns, and incident debrief sessions, with photographic or documented evidence.","Establish a non-punitive incident reporting policy in writing, communicate it at orientation and refresher training, and record the number of staff trained to demonstrate culture commitment."]'::jsonb where oe_code = 'PSQ.4.a';
update public.shco_full_oes set achieve_tips = '["Conduct an annual orientation for all department heads and supervisors covering the objectives, scope, and implementation approach of the patient safety and quality improvement programme.","Maintain attendance records and brief assessment results from leadership awareness sessions so assessors can verify that knowledge is not limited to the quality team alone.","Include patient safety and quality programme updates as a standing agenda item in monthly leadership meetings, ensuring leaders receive current information and can speak to it during assessor interviews.","Create a one-page programme summary for leaders outlining key indicators, ongoing projects, and improvement priorities, updated quarterly and distributed before assessor visits."]'::jsonb where oe_code = 'PSQ.4.b';
update public.shco_full_oes set achieve_tips = '["Include a specific budget line for patient safety and quality improvement in the annual financial plan, covering training, audit tools, software, and improvement project costs.","Maintain records of expenditure against the quality budget — purchase orders, invoices, and training costs — to demonstrate that funds earmarked for quality are actually utilised.","Create an SOP for requesting quality-related resources that ensures requests are processed promptly and linked to an identified patient safety or quality improvement need.","During assessor interviews, the quality coordinator should be able to cite at least two resources — staffing, equipment, or training — specifically provided by management to support quality activities."]'::jsonb where oe_code = 'PSQ.4.c';
update public.shco_full_oes set achieve_tips = '["Deploy an annual staff satisfaction and safety culture survey, analyse results by department, and share a summary report with management along with a formal improvement response plan.","Establish a structured mechanism — such as a suggestion box, digital feedback form, or monthly safety debrief — for frontline staff to raise safety concerns directly to management.","Document each piece of staff feedback received, the management''s response, and any programme change made as a result, creating an auditable feedback loop for assessors.","Track the number and nature of staff-generated safety suggestions year-on-year to demonstrate that the feedback mechanism is active, used, and linked to measurable programme changes."]'::jsonb where oe_code = 'PSQ.4.d';
update public.shco_full_oes set achieve_tips = '["Implement a standardised incident reporting form and a clear reporting pathway so every staff member knows exactly how to report an incident — from verbal notification to written documentation.","Maintain an incident register that captures incident type, date, location, severity, staff involved, and actions taken, and make it available for assessor review at any time.","Train all clinical and support staff at induction and annually on the incident reporting system, maintaining signed attendance records as evidence of training coverage.","During assessor walkthroughs, staff should demonstrate familiarity with the incident form and be able to describe the steps they would follow if they witnessed or were involved in an incident."]'::jsonb where oe_code = 'PSQ.5.a';
update public.shco_full_oes set achieve_tips = '["Define a written list of events that meet the facility''s sentinel event criteria — such as wrong-site surgery, patient suicide, or maternal death — and distribute it to all clinical leads.","Create a sentinel event reporting SOP with clear escalation steps, timelines for notification to management and regulatory bodies, and documentation requirements.","Train charge nurses and department heads to recognise sentinel event criteria and initiate the reporting pathway immediately, without waiting for management instruction.","Maintain a sentinel event register — even if entries are rare — and document each event''s root cause analysis and corrective action to demonstrate an active identification and response system."]'::jsonb where oe_code = 'PSQ.5.b';
update public.shco_full_oes set achieve_tips = '["Develop a written SOP for incident analysis that specifies when root cause analysis is required, who conducts it, the timeline for completion, and how findings are documented and shared.","For every significant incident, complete a structured root cause analysis using a validated tool such as the fishbone diagram or five-whys method, and retain the completed analysis form.","Conduct monthly trend analysis of incident data by category — medication, falls, infection, documentation — and present findings with visual trend charts at the quality committee meeting.","Train the quality team and clinical leads in incident analysis methodology so that investigations are systematic, consistent, and produce actionable findings rather than superficial conclusions."]'::jsonb where oe_code = 'PSQ.5.c';
update public.shco_full_oes set achieve_tips = '["For every incident analysis, generate a formal corrective and preventive action plan with specific tasks, responsible owners, implementation deadlines, and verification methods.","Track CAPA completion status in a register and review it monthly at quality meetings — overdue actions should be escalated to senior management for resolution.","After implementing a corrective action, conduct a follow-up audit or observation within 60 days to verify the action has been embedded in practice and has reduced the risk of recurrence.","Document preventive actions separately from corrective actions — show assessors that the facility learns from individual incidents to prevent similar events in other departments."]'::jsonb where oe_code = 'PSQ.5.d';
update public.shco_full_oes set achieve_tips = '["Develop a stakeholder communication SOP that specifies who must be notified — patient, family, medical staff, management, and regulators — within defined timeframes for near misses, adverse events, and sentinel events.","Maintain a communication log for each significant event recording who was informed, when, by whom, and what information was shared, ensuring full traceability for assessors.","Train clinical and administrative staff on patient and family communication protocols following adverse events, including empathetic disclosure language and documentation of what was discussed.","Conduct periodic drills or tabletop exercises simulating an adverse event scenario to verify that the notification pathway works in practice and all staff know their communication responsibilities."]'::jsonb where oe_code = 'PSQ.5.e';
